28|int LLVMFuzzerTestOneInput(const uint8_t *data, size_t dataLen) {
29|
30|    gzFile file;
31|    char fname[] = "gzio.XXXXXX";
32|    close(mkstemp(fname));
33|    unsigned mode_sz = (dataLen ? (--dataLen, *data++) | 2 : 8) & 0xF;
34|    char mode[mode_sz];
35|    memcpy(mode, data, dataLen >= mode_sz ? mode_sz - 1: dataLen);
36|    mode[mode_sz - 1] = 0;
37|    file = gzopen(fname, mode);
38|
39|    /* Chain I/O operations on a file opened with random mode the nature of the
40|     * operation and their operand are controlled by the fuzzer
41|     */
42|    int op_count = 2; //< Number of operations chained.
43|    while(op_count-- && dataLen > 0) {
44|      switch((--dataLen, (*data++)%26)) {
45|        case 0: {
46|          char c = dataLen ? (--dataLen, (char)*data++) : 'c';
47|          if(gzputc(file, c) < 0) {
48|            goto exit;
49|          }
50|          break;
51|        }
52|        case 1: {
53|          unsigned sz = dataLen ? ((--dataLen, *data++)&0xF) + 1 : 8;
54|          char input[sz];
55|          memcpy(input, data, dataLen >= sz ? sz - 1: dataLen);
56|          input[sz - 1] = 0;
57|          if(gzputs(file, input) < 0)
58|            goto exit;
59|          break;
60|        }
61|        case 2: {
62|          unsigned sz = dataLen ? ((--dataLen, *data++)&0xF) + 1 : 8;
63|          unsigned nitems = dataLen ? ((--dataLen, *data++)&0xF) + 1 : 8;
64|          unsigned count = sz * nitems;
65|          char input[count];
66|          memcpy(input, data, dataLen >= count ? count - 1: dataLen);
67|          input[count - 1] = 0;
68|          if(gzfwrite(input, sz, nitems, file) <= 0)
69|            goto exit;
70|          break;
71|        }
72|        case 3: {
73|          unsigned sz = dataLen ? (--dataLen, *data++) : 8;
74|          char uncompr[sz];
75|          if(gzread(file, uncompr, sz) < 0)
76|            goto exit;
77|          break;
78|        }
79|        case 4: {
80|          int whences[5] = {SEEK_CUR, SEEK_SET, SEEK_END, 18};
81|          int whence = dataLen ? (--dataLen, whences[(*data++)%6]) : SEEK_CUR;
82|          long offset = dataLen >= sizeof(long) ? (*(long*)data &0xFF) + 1: 1L;
83|          if(gzseek(file, offset, whence) < 0)
84|            goto exit;
85|          break;
86|        }
87|        case 5:
88|          gztell(file);
89|          break;
90|        case 6:
91|          gzgetc(file);
92|          break;
93|        case 7: {
94|          char c = dataLen ? (--dataLen, (char)*data++) : 'c';
95|          if(gzungetc(c, file) < 0)
96|            goto exit;
97|          break;
98|        }
99|        case 8: {
100|          unsigned sz = dataLen ? (--dataLen, *data++) : 8;
101|          char uncompr[sz];
102|          if(gzgets(file, uncompr, sz) < 0)
103|            goto exit;
104|          break;
105|        }
106|        case 9: {
107|          int level = dataLen ? (--dataLen, *data++) : 1;
108|          int strat = dataLen ? (--dataLen, *data++) : 2;
109|          if(gzsetparams(file, level, strat) < 0)
110|            goto exit;
111|          break;
112|        }
113|        case 10: {
114|          int flush = dataLen ? (--dataLen, *data++) : 0;
115|          gzflush(file, flush); break;
116|        }
117|        case 11: {
118|          static const char formats [][4] = { "%d", "%f", "%c", "%s" };
119|          int nformat = dataLen ? (--dataLen, *data++)%5 : 1;
120|          switch(nformat) {
121|            case 0: {
122|              int value = dataLen >= sizeof(int) ? *(int*)data : 1;
123|              gzprintf(file, formats[nformat], value);
