135|            }
136|            case 3: {
137|             unsigned sz = dataLen ? ((--dataLen, *data++)&0xF)+1 : 8;
138|             char input[sz];
139|             memcpy(input, data, dataLen >= sz ? sz - 1: dataLen);
140|             input[sz - 1] = 0;
